<script lang="ts">
 import PublicLayout from '$lib/components/public/PublicLayout.svelte';import {publicHref,publicLabels,type PublicType} from '$lib/content/public';let {data}=$props();
 const identity=$derived(data.identity as {siteName:string;intro?:string;banner?:import('$lib/components/public/SceneBanner.svelte').Banner|null});
 function pageHref(page:number){const q=new URLSearchParams({q:data.input.q,page:String(page)});for(const t of data.input.type)q.append('type',t);for(const t of data.input.tag)q.append('tag',t);return `/search?${q}`;}
</script>
<svelte:head><title>搜索 · 个人综合站</title><meta name="robots" content="noindex,follow" /></svelte:head>
<PublicLayout tools={data.hasTools} siteName={identity.siteName} intro={identity.intro ?? ''} banner={identity.banner ?? null}><main class="search-page"><div class="search-orbit" aria-hidden="true">✦</div><p class="eyebrow">FIND SOMETHING</p><h1>搜索</h1><p class="lede">从标题、摘要、正文和标签中查找公开内容。</p><form method="GET" action="/search"><label>关键词<input name="q" value={data.input.q} maxlength="200" placeholder="输入关键词，最多 8 个片段" /></label><fieldset><legend>内容类型</legend>{#each Object.entries(publicLabels) as [type,label]}<label class="check"><input type="checkbox" name="type" value={type} checked={data.input.type.includes(type)}/>{label}</label>{/each}</fieldset>{#if data.tags.length}<fieldset><legend>标签</legend>{#each data.tags as tag}<label class="check"><input type="checkbox" name="tag" value={tag.id} checked={data.input.tag.includes(tag.id)}/>{tag.name}</label>{/each}</fieldset>{/if}<button class="primary">搜索 <span aria-hidden="true">↗</span></button></form>
{#if data.result.error}<p role="alert" class="error">{data.result.error}</p><a href={pageHref(data.result.page)}>保留条件重试</a>{:else if !data.result.terms.length}<p>输入关键词开始搜索。</p>{:else}<p role="status">共 {data.result.total} 条</p>{#if !data.result.items.length}<p>{data.result.page>1?'已超出最后一页。':'没有找到公开内容。'}</p>{#if data.result.page>1}<a href={pageHref(1)}>返回第一页</a>{/if}{:else}<ol>{#each data.result.items as item}<li><a href={publicHref(item.type as PublicType,item.slug)}><h2>{item.title||item.summary||publicLabels[item.type]}</h2></a><p>{@html item.snippet}</p><p class="muted">{publicLabels[item.type]} · {new Date(item.first_published_at).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}</p></li>{/each}</ol>{/if}<nav aria-label="搜索分页">{#if data.result.page>1}<a href={pageHref(data.result.page-1)}>上一页</a>{/if}{#if data.result.total!==null&&data.result.page*20<data.result.total}<a href={pageHref(data.result.page+1)}>下一页</a>{/if}</nav>{/if}</main></PublicLayout>
<style>.search-page{position:relative;max-width:900px;margin:auto}.search-orbit{position:absolute;right:10px;top:4px;color:var(--accent-pink);font-size:48px;transform:rotate(15deg)}.eyebrow{margin:0 0 10px;color:var(--primary);font:700 12px/1.2 'JetBrains Mono',monospace;letter-spacing:.14em}.search-page h1{margin:0;font-size:clamp(30px,4vw,40px);letter-spacing:-.035em}.lede{margin:12px 0 32px;color:var(--muted);font-size:16px}.search-page form{padding:24px;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius-md);box-shadow:var(--shadow-sm)}fieldset{display:flex;flex-wrap:wrap;gap:8px 24px;margin-block:16px;border:1px solid var(--line);border-radius:12px;padding:12px 16px}fieldset label{margin:0}ol{list-style:none;padding:0}li{padding:24px 0;border-bottom:1px solid var(--line)}li h2{margin:0 0 8px;font-size:22px}li p{margin:6px 0}nav{display:flex;gap:24px;margin:24px 0}nav a{min-height:44px;padding:8px}
</style>
